const profileAvatar=user=>{const label='查看'+name(user)+'的主页';return user?.id?`<a class="cm-message-avatar" href="#community/user/${esc(user.id)}" data-cm="group-nav" aria-label="${esc(label)}" title="${esc(label)}">${avatar(user)}</a>`:`<span class="cm-message-avatar" aria-label="社区用户头像">${avatar(user)}</span>`;};
