const routeFor=id=>'#community/messages/group/'+encodeURIComponent(id);
const allRole=group=>['owner','admin'].includes(group?.role);
const imageDraft=images=>Array.isArray(images)?images.filter(image=>image&&typeof image.id==='string'&&/^image\/(jpeg|png|webp)$/.test(image.type||'')).slice(0,9).map(image=>({...image})):[];
