  tabs() {return '<nav class="cm-message-tabs cm-group-message-tabs" aria-label="消息类型"><a href="#community/messages" data-cm="group-nav">私信</a><a href="#community/messages/groups" data-cm="group-nav" aria-current="page" class="active" aria-label="群聊">群聊<span class="cm-group-entry-badge" hidden></span></a></nav>';}
