    this.layout=this.page().querySelector('.cm-groups-layout');this.list={items:[],hasMore:true,loaded:false};this.resizeObserver=new ResizeObserver(this.resizeBound);this.resizeObserver.observe(this.layout);window.addEventListener('resize',this.resizeBound);window.visualViewport?.addEventListener('resize',this.resizeBound);window.visualViewport?.addEventListener('scroll',this.resizeBound);this.resizeListening=true;this.resize();
