      try{const result=await this.owner.api.get('/groups/'+encodeURIComponent(id));if(!this.viewAlive(epoch))return;state.group=result.group;state.items=[];state.fetchAfter='0';state.readId=null;state.cursor=null;state.hasMore=true;state.unavailable=false;this.renderChat(state);await this.loadHistory(true);}
