    holder.innerHTML=list.items.map(group=>`<a class="cm-group-row ${this.current?.id===group.id?'active':''}" data-group-id="${esc(group.id)}" data-cm="group-nav" href="${routeFor(group.id)}" ${this.current?.id===group.id?'aria-current="page"':''}>${groupAvatar()}<div class="cm-group-row-copy"><header><h2>${esc(group.name)}</h2><time>${group.lastMessage?when(group.lastMessage.createdAt):''}</time></header><p>${group.mentionUnreadCount?'<strong class="cm-group-mentioned">有人@我</strong> ':''}${esc(group.lastMessage?name(group.lastMessage.sender)+'：'+messagePreview(group.lastMessage):'群号 '+group.groupNumber+' · '+group.memberCount+' 人')}</p></div>${group.unreadCount?`<span class="cm-conversation-unread">${group.unreadCount>99?'99+':group.unreadCount}</span>`:''}</a>`).join('');
