    this.page().querySelector('.cm-messages-pane').innerHTML=`<section class="cm-chat cm-group-chat"><header class="cm-chat-header"><a href="#community/messages/groups" data-cm="group-nav" class="cm-icon-button cm-chat-back" aria-label="返回群列表">${icon('back')}</a><div class="cm-group-chat-heading"></div><button type="button" data-cm="group-info" data-id="${esc(state.id)}" class="cm-icon-button" aria-label="群资料与管理" title="群资料与管理">${icon('more')}</button></header><div class="cm-group-announcement" hidden></div><div class="cm-group-message-list cm-message-list" tabindex="0" role="log" aria-live="polite" aria-label="群聊天记录"><div class="cm-group-history"></div><div class="cm-group-messages-body"></div></div><button type="button" data-cm="group-bottom" class="cm-chat-new" hidden>有新消息，回到底部</button><form class="cm-group-compose" data-cm-form="group-message"><div class="cm-group-mention-chips"></div><div class="cm-group-image-composer"></div><label class="cm-sr" for="cm-group-message-input">群消息</label><textarea id="cm-group-message-input" name="body" maxlength="1000" rows="2" placeholder="和群成员聊聊…"></textarea><div class="cm-group-composer-bottom"><button type="button" data-cm="group-mentions" class="cm-button cm-group-at" aria-label="选择要提醒的群成员">@ 提醒</button><span class="cm-group-compose-status" role="status"></span><button type="submit" class="cm-button cm-primary cm-group-send">${icon('send')}发送</button></div><div class="cm-group-compose-error" role="alert" hidden></div></form></section>`;
