  showCreate() {this.showDialog('创建群聊','<form data-cm-form="group-create"><p class="cm-form-help">创建后你将成为群主，可以设置管理员、公告和发言权限。</p><label>群名称<input name="name" maxlength="30" required placeholder="给群聊起个名字"></label><label>群简介<textarea name="description" maxlength="120" rows="2" placeholder="介绍群聊的主题（选填）"></textarea></label><label>群公告<textarea name="announcement" maxlength="500" rows="3" placeholder="欢迎语或群规则（选填）"></textarea></label><button type="submit" class="cm-button cm-primary">创建群聊</button></form>');}
